    "welcome.sub": "একটি উষ্ণ ছোট শহর যেখানে প্রতিবেশীরা নতুন ভাষায় অভিবাদন বিনিময় করে। যেকোনো ব্যক্তির কাছে যান, অভিবাদন জানান এবং দিনটি আপনাকে শেখাক।",
    "welcome.you.title": "আপনি আপনি",
    "welcome.you.bodyNamed": "আপনার কাগজের স্ব, {name}, প্রস্তুত এবং সাজানো।",
