// GENERATED_LOCALES_END

/* ===================================================== resolver / RTL ====== */

/**
 * Collapse a stack/manifest code to its base translation locale, matching the
 * Corpán corpus convention (ko-polite→ko, pt-BR→pt, zh-Hans→zh, pa-Guru→pa).
 * Lowercased; the part before the first `-`.
 */
export function baseLocale(lang: string): string {
  return (lang || "en").split("-")[0].toLowerCase()
}

const RTL_BASE = new Set(["ar", "he", "fa", "ur"])

/** True when `lang`'s script runs right-to-left (Arabic, Hebrew, Farsi, Urdu). */
export function isRtl(lang: string): boolean {
  return RTL_BASE.has(baseLocale(lang))
}

/** The HTML `dir` value for a native locale ("rtl" | "ltr"). */
export function dirFor(lang: string): "rtl" | "ltr" {
  return isRtl(lang) ? "rtl" : "ltr"
}

/**
 * Orient an element (the pack root / `.wp-overlay`) for `lang`: sets `dir` and a
 * `lang` attribute so the chrome's logical CSS properties mirror under RTL. Safe
 * to call repeatedly (idempotent); a no-op outside the DOM.
 */
export function applyDir(root: HTMLElement | null | undefined, lang: string): void {
  if (!root) return
  try {
    root.setAttribute("dir", dirFor(lang))
    root.setAttribute("lang", baseLocale(lang))
  } catch (err) {
    console.error("[wp/i18n] applyDir failed:", err)
  }
}

function interpolate(s: string, params?: Record<string, string | number>): string {
  if (!params) return s
  // Replace every {token} in one pass; unknown tokens are left intact so a typo
  // is visible rather than silently dropped.
  return s.replace(/\{(\w+)\}/g, (m, k) => (k in params ? String(params[k]) : m))
}

// Dev-only: warn ONCE per (key, lang) when a locale that should be complete
// falls back to English (MEMORY "noisy errors" — never silent). En is exempt.
const warned = new Set<string>()

/**
 * Translate `key` into `lang` (the learner's NATIVE language), interpolating
 * `{token}` params. Resolution order: exact locale → base-collapsed locale →
 * English. Never blank — falls back per-key to English.
 */
export function t(
  key: I18nKey,
  lang: string,
  params?: Record<string, string | number>,
): string {
  const loc = baseLocale(lang)
  const hit = LOCALES[lang]?.[key] ?? LOCALES[loc]?.[key]
  const value = hit ?? en[key]
  if (hit === undefined && loc !== "en" && LOCALES[loc]) {
    // The locale exists but is missing THIS key — surface it once in dev.
    const tag = `${loc}:${key}`
    if (!warned.has(tag)) {
      warned.add(tag)
      console.warn(`[wp/i18n] missing "${key}" for "${loc}" — using English`)
    }
  }
  return interpolate(value, params)
}

/** A `t` bound to one native locale — the shape most surfaces consume. */
export type BoundT = (key: I18nKey, params?: Record<string, string | number>) => string

/** Bind `t` to a native locale so a surface can call `bt(key, params)`. */
export function bindT(lang: string): BoundT {
  return (key, params) => t(key, lang, params)
}

/** The set of locales actually present in the committed table (for tests/dev). */
export function presentLocales(): string[] {
  return Object.keys(LOCALES)
}

/** The English source dict (for the missing-key CI test). */
export const SOURCE_EN: Readonly<Dict> = en

/** All keys (for the missing-key CI test). */
export const ALL_KEYS = Object.keys(en) as I18nKey[]

export { LOCALES as __LOCALES_FOR_TEST }
